exercise.solution:
CREATE TABLE lab_l06_users (
  id SERIAL PRIMARY KEY,
  name VARCHAR(120) NOT NULL
);

CREATE TABLE lab_l06_profiles (
  id SERIAL PRIMARY KEY,
  title VARCHAR(200) NOT NULL,
  user_id INTEGER NOT NULL UNIQUE REFERENCES lab_l06_users(id)
);

